params.command:
$ErrorActionPreference='Stop'
$relay=Join-Path $env:USERPROFILE 'HeavenBridgeRepo'
$tmp=Join-Path $env:USERPROFILE 'mhw-safe-branch-delete'
if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
$url=(git -C $relay remote get-url origin).Trim()
git clone --no-local $relay $tmp | Out-Null
git -C $tmp remote set-url origin $url
git -C $tmp fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune
$deleted=@(); $kept=@(); $failed=@()
$branches=git -C $tmp for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object { $_ -ne 'origin/HEAD' }
foreach($rb in $branches){
  $b=$rb -replace '^origin/',''
  if($b -in @('main','heaven-bridge')) { continue }
  $branchOnly=[int](git -C $tmp rev-list --right-only --count "origin/main...origin/$b")
  if($branchOnly -eq 0){
    $out = git -C $tmp push origin --delete $b 2>&1
    if($LASTEXITCODE -eq 0){ $deleted += $b } else { $failed += [pscustomobject]@{branch=$b;error=[string]$out} }
  } else {
    $kept += [pscustomobject]@{branch=$b;unique_commits=$branchOnly}
  }
}
git -C $tmp fetch origin --prune | Out-Null
[pscustomobject]@{deleted=$deleted;deleted_count=$deleted.Count;kept=$kept;kept_count=$kept.Count;failed=$failed;failed_count=$failed.Count} | ConvertTo-Json -Depth 6 -Compress
